import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble: capped at nine active factors, all positive direction.
FACTORS = {"clv1": .20, "leadlag5": .18, "mom20": .16, "rev5": .11,
           "cons_mom20": .10, "down20": .09, "rev3": .06,
           "clvtrend15": .06, "eff20": .04}
MIN_W, MAX_W = .02, .15
_day = 0

def cs_rank(values):
    out = {s: .5 for s in ASSETS}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out

def bounded_weights(score):
    w = {s: MIN_W for s in ASSETS}
    free = 1.0 - MIN_W * len(ASSETS)
    active = set(ASSETS)
    while active and free > 1e-12:
        q = {s: max(float(score.get(s, .5)), .01) for s in active}
        total = sum(q.values())
        hit = [s for s in active if free * q[s] / total > MAX_W - MIN_W]
        if not hit:
            for s in active:
                w[s] += free * q[s] / total
            break
        for s in hit:
            w[s] = MAX_W
            free -= MAX_W - MIN_W
            active.remove(s)
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}

@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % 10 != 0:
        return
    data = {}
    for symbol in ASSETS:
        df = get_stock_daily_data(symbol=symbol, days=110)
        if df is None or len(df) < 40:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        lo = np.asarray(df["low"], dtype=float)
        if len(c) < 32 or not np.all(np.isfinite(c[-32:])) or c[-1] <= 0:
            continue
        ret = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        vol = max(float(np.std(ret[-20:])), .008)
        downvol = max(float(np.std(np.minimum(ret[-20:], 0.0))), .004)
        rng = np.maximum(h[-20:] - lo[-20:], 1e-12)
        clv_hist = (2*c[-20:] - h[-20:] - lo[-20:]) / rng
        r5, r20 = c[-1] / c[-6] - 1.0, c[-1] / c[-21] - 1.0
        # Consistency gate rewards positive, steady 20d trends and avoids
        # relying on a single recent jump.
        consistency = float(np.mean(ret[-20:] > 0))
        data[symbol] = {"clv1": (2*c[-1]-h[-1]-lo[-1]) / max(h[-1]-lo[-1], 1e-12),
                        "r5": r5, "rev5": -float(np.mean(ret[-5:])),
                        "rev3": -float(np.mean(ret[-3:])), "mom20": r20/(vol+.01),
                        "cons_mom20": r20/(vol+.01) * (0.5 + consistency),
                        "down20": r20/(downvol+.01), "eff20": r20/(downvol+.015),
                        "clvtrend15": float(np.mean(clv_hist[-15:])),
                        "trend": c[-1]/c[-31]-1.0, "invvol": 1.0/vol}
    if len(data) < 10:
        return
    median_r5 = float(np.median([v["r5"] for v in data.values()]))
    raw = {f: {} for f in FACTORS}
    for s, v in data.items():
        for f in FACTORS:
            raw[f][s] = v[f] if f != "leadlag5" else v["r5"] - median_r5
    ranks = {f: cs_rank(raw[f]) for f in FACTORS}
    score = {s: sum(FACTORS[f] * ranks[f][s] for f in FACTORS) for s in ASSETS}

    # Full-investment defensive tilt in bearish or unstable conditions.
    equity = [data[s] for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "NDX") if s in data]
    breadth = sum(v["trend"] > 0 for v in equity) / max(len(equity), 1)
    median_vol = float(np.median([1.0 / v["invvol"] for v in data.values()]))
    bear = len(equity) >= 3 and (breadth <= .50 or (data.get("SPX", {}).get("trend", 0) < 0 and data.get("SPX", {}).get("r5", 0) < 0))
    unstable = median_vol > .018 or breadth < .67
    if bear or unstable:
        bump = .10 if bear else .045
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] = score.get(s, .5) + bump
        for s in ("BTC", "ETH", "WTI"):
            score[s] = max(.02, score.get(s, .5) - (.05 if bear else .02))
    med_invvol = float(np.median([v["invvol"] for v in data.values()]))
    for s in ASSETS:
        score[s] = max(.02, score[s]) * (.95 + .05 * data.get(s, {}).get("invvol", med_invvol) / max(med_invvol, 1e-12))
    target = bounded_weights(score)
    if len(target) == 15 and abs(sum(target.values()) - 1.0) < 1e-8 and all(np.isfinite(v) and v >= 0 for v in target.values()):
        rebalance_to_weights(target)

