# Screener ensemble, capped at seven active factors and no reactive reversal sleeve.
FACTORS = {"downmom": .24, "eff": .22, "cons20": .16, "cons30": .13,
           "persist": .10, "resid": .09, "lead": .06}
MIN_W, MAX_W = .03, .15
_day = 0


def rank_cs(vals):
    out = {s: .5 for s in ASSETS}
    good = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / n if n > 1 else .5
    return out


def bounded_weights(score):
    raw = {s: max(.10, float(score.get(s, .5))) for s in ASSETS}
    w = {s: MIN_W + (1 - MIN_W * len(ASSETS)) * raw[s] / sum(raw.values()) for s in ASSETS}
    # Iterative cap redistribution preserves a complete, non-negative vector.
    for _ in range(20):
        over = [s for s in ASSETS if w[s] > MAX_W]
        if not over:
            break
        excess = sum(w[s] - MAX_W for s in over)
        for s in over:
            w[s] = MAX_W
        free = [s for s in ASSETS if s not in over]
        den = sum(raw[s] for s in free)
        for s in free:
            w[s] += excess * raw[s] / den
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % 10:
        return
    data = {}
    for s in ASSETS:
